CREATE TABLE IF NOT EXISTS audit_integrity_checkpoints (id CHAR(36) PRIMARY KEY, first_audit_id BIGINT NOT NULL, last_audit_id BIGINT NOT NULL, record_count INT NOT NULL, previous_digest CHAR(64) NULL, content_digest CHAR(64) NOT NULL, sealed_by INT NOT NULL, sealed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_audit_checkpoint_range (first_audit_id,last_audit_id), INDEX idx_audit_checkpoint_time (sealed_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS privileged_access_requests (id CHAR(36) PRIMARY KEY, user_id INT NOT NULL, permission_name VARCHAR(100) NOT NULL, scope_type VARCHAR(40) NOT NULL DEFAULT 'ORGANISATION', scope_id VARCHAR(120) NULL, requested_by INT NOT NULL, approved_by INT NULL, reason VARCHAR(500) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING_APPROVAL', starts_at DATETIME NULL, expires_at DATETIME NOT NULL, approved_at DATETIME NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_jit_user_status (user_id,status,expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS access_review_campaigns (id CHAR(36) PRIMARY KEY, name VARCHAR(160) NOT NULL, scope_json JSON NOT NULL, due_at DATETIME NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'OPEN', created_by INT NOT NULL, completed_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_access_review_status (status,due_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS access_review_decisions (id CHAR(36) PRIMARY KEY, campaign_id CHAR(36) NOT NULL, user_id INT NOT NULL, reviewer_id INT NOT NULL, decision VARCHAR(20) NOT NULL, reason VARCHAR(500) NOT NULL, decided_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE KEY uq_review_decision (campaign_id,user_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS segregation_policies (id CHAR(36) PRIMARY KEY, policy_key VARCHAR(100) NOT NULL UNIQUE, permission_a VARCHAR(100) NOT NULL, permission_b VARCHAR(100) NOT NULL, severity VARCHAR(20) NOT NULL DEFAULT 'HIGH', active TINYINT(1) NOT NULL DEFAULT 1, updated_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS security_risk_exceptions (id CHAR(36) PRIMARY KEY, control_key VARCHAR(120) NOT NULL, owner_id INT NOT NULL, reason VARCHAR(700) NOT NULL, compensating_controls VARCHAR(1000) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING_APPROVAL', requested_by INT NOT NULL, approved_by INT NULL, expires_at DATETIME NOT NULL, approved_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_risk_exception_status (status,expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS cryptographic_key_versions (key_name VARCHAR(100) NOT NULL, key_version VARCHAR(30) NOT NULL, purpose VARCHAR(300) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'DECRYPT_ONLY', activated_at DATETIME NULL, retired_at DATETIME NULL, fingerprint_sha256 CHAR(64) NOT NULL, recorded_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(key_name,key_version)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS service_accounts (id CHAR(36) PRIMARY KEY, account_name VARCHAR(120) NOT NULL UNIQUE, owner_user_id INT NOT NULL, purpose VARCHAR(500) NOT NULL, scopes_json JSON NOT NULL, expires_at DATETIME NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', last_reviewed_at DATETIME NULL, created_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_service_account_status (status,expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS security_event_outbox (id CHAR(36) PRIMARY KEY, event_type VARCHAR(100) NOT NULL, destination_key VARCHAR(100) NOT NULL, payload_json JSON NOT NULL, payload_sha256 CHAR(64) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', attempts INT NOT NULL DEFAULT 0, next_attempt_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, delivered_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_security_outbox_delivery (status,next_attempt_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS resilience_exercises (id CHAR(36) PRIMARY KEY, exercise_type VARCHAR(60) NOT NULL, scenario VARCHAR(700) NOT NULL, started_at DATETIME NOT NULL, completed_at DATETIME NULL, recovery_minutes INT NULL, evidence_sha256 CHAR(64) NOT NULL, result VARCHAR(30) NOT NULL, findings VARCHAR(1200) NOT NULL, conducted_by INT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_resilience_exercise_time (started_at,result)) ENGINE=InnoDB;
